Find numeric columns with >= 80% of usage

{noformat}DELIMITER $$
DROP PROCEDURE IF EXISTS infra.determine_column_usage $$
CREATE PROCEDURE infra.determine_column_usage()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE percentage FLOAT(4,2) DEFAULT 0.00;
    DECLARE str_SCHEMA, str_TABLE,  str_COLUMN, str_TYPE VARCHAR(64);
    DECLARE num_MAX_LIMIT BIGINT UNSIGNED;
    DECLARE cur1 CURSOR FOR  SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME, DATA_TYPE,
        (CASE DATA_TYPE
        WHEN 'tinyint' THEN IF(COLUMN_TYPE LIKE '%unsigned', 255, 127)
        WHEN 'smallint' THEN IF(COLUMN_TYPE LIKE '%unsigned', 65535, 32767)
        WHEN 'mediumint' THEN IF(COLUMN_TYPE LIKE '%unsigned', 16777215, 8388607)
        WHEN 'int' THEN IF(COLUMN_TYPE LIKE '%unsigned', 4294967295, 2147483647)
        WHEN 'bigint' THEN IF(COLUMN_TYPE LIKE '%unsigned', 18446744073709551615, 9223372036854775807)
        END) max_limit
        FROM information_schema.COLUMNS
        WHERE DATA_TYPE LIKE '%int' AND TABLE_SCHEMA NOT IN('sys', 'mysql', 'information_schema', 'performance_schema');
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cur1;

    columns: LOOP
        FETCH cur1 INTO str_SCHEMA, str_TABLE, str_COLUMN, str_TYPE, num_MAX_LIMIT;
        IF done THEN
            LEAVE columns;
        END IF;

        SET @query = CONCAT('SELECT IFNULL(MAX(`',str_COLUMN,'``),0) INTO @num_MAX_VALUE FROM ',str_SCHEMA,'.',str_TABLE,';');
        PREPARE stmt FROM @query;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;

        -- SET percentage = 0.00;
        -- SET percentage = (@num_MAX_VALUE * 100) / num_MAX_LIMIT;

        IF ((@num_MAX_VALUE * 100) / num_MAX_LIMIT) >= 80.00 THEN
            SELECT str_SCHEMA, str_TABLE, str_COLUMN, str_TYPE, num_MAX_LIMIT, @num_MAX_VALUE, (@num_MAX_VALUE * 100) / num_MAX_LIMIT;
        END IF;

    END LOOP;

    CLOSE cur1;
END $$
DELIMITER ;{noformat}

